NEW = {'brain/planner.py': '"""\nЦикл мышления Atlas: понять → (план → выполнить) → ответить. Модель зовётся как можно реже.\n\n    _brain_ask(question, speech)  — один ход разговора\n    execute_plan(...)             — несколько действий подряд без модели (или в фоне)\n    рабочая память                — цель, последние действия, последний ответ («запиши туда ещё»)\n    короткий ответ                — результат простого инструмента → фраза крошечным запросом\n    портрет пользователя          — главное о человеке из графа памяти\n"""\nimport concurrent.futures\nimport json\nimport os\nimport re\nimport threading\nimport time\nfrom datetime import datetime\n\nimport tool_router\nfrom brain import prompt, providers, state, tools\nfrom brain.state import TaskCancelled, _check_cancel\nfrom core import llm_gateway\nfrom core import memory\nfrom database import log_task\n\n_ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\n\n\ndef _lang_ru(question: str) -> bool:\n    return "(Respond in Russian.)" in question\n\n\n# =============================================================================\n# Рабочая память\n# =============================================================================\n_AUTO_WAIT_AFTER = {"open_app", "launch_steam_game", "open_url", "open_file", "open_found_file", "open_deep_link",\n                    "play_on_spotify", "open_youtube", "open_vscode_project"}\n\n\ndef _short_args(args: dict) -> str:\n    return ", ".join(f"{k}={str(v)[:30]}" for k, v in (args or {}).items())[:90]\n\n\ndef _note_action(name: str, args: dict, ok: bool) -> None:\n    if name in ("execute_plan", "update_plan"):\n        return\n    state.situation["actions"].append(f"{name}({_short_args(args)}) {\'ok\' if ok else \'FAILED\'}")\n    del state.situation["actions"][:-8]\n\n\ndef _situation_msg():\n    s, parts = state.situation, []\n    if s["goal"]:\n        parts.append(f"current goal: {s[\'goal\']}")\n    if s["actions"]:\n        parts.append("recent actions: " + "; ".join(s["actions"][-6:]))\n    if s["reply"]:\n        parts.append(f"your last reply: {s[\'reply\'][:160]}")\n    if not parts:\n        return None\n    return {"role": "system", "content": "Situation (use it to continue tasks and resolve \'it/this/there\'): " + " | ".join(parts)}\n\n\n# =============================================================================\n# План: несколько действий подряд без модели\n# =============================================================================\ndef _exec_steps(steps: list, cancellable: bool = True):\n    """→ (всё ли удалось, отчёт по шагам)."""\n    lines = []\n    for i, st in enumerate(steps or [], 1):\n        if cancellable:\n            _check_cancel()\n        if not isinstance(st, dict):\n            continue\n        name = str(st.get("tool") or "").strip()\n        if not name and st.get("wait") is not None:\n            time.sleep(min(10.0, max(0.0, float(st.get("wait") or 0))))\n            continue\n        if name not in tools.AVAILABLE_FUNCTIONS or name == "execute_plan":\n            lines.append(f"{i}. {name}: no such tool — use a real tool name")\n            return False, lines\n        args = st.get("args") if isinstance(st.get("args"), dict) else {}\n        res, ok, _ms = tools._run_one_tool(name, dict(args))\n        ok = ok and not tools._TRACE_FAIL.search(str(res)[:220])\n        _note_action(name, args, ok)\n        lines.append(f"{i}. {name} → {\'OK\' if ok else \'FAILED\'}: {str(res)[:300]}")\n        if not ok:\n            return False, lines\n        nxt = steps[i] if i < len(steps) else None\n        if (name in _AUTO_WAIT_AFTER and isinstance(nxt, dict) and nxt.get("wait") is None\n                and str(nxt.get("tool") or "").startswith(("desktop_", "browser_"))):\n            time.sleep(1.5)                       # окно программы должно успеть появиться\n        if st.get("wait"):\n            time.sleep(min(10.0, float(st["wait"])))\n    return True, lines\n\n\ndef execute_plan(goal: str, steps: list, done_message: str = "", background: bool = False) -> str:\n    """Runs several actions in order, instantly, in one go."""\n    state.situation["goal"] = str(goal)[:160]\n    if background:\n        def run():\n            ok, lines = _exec_steps(steps, cancellable=False)\n            try:\n                from voice import get_response_language\n                ru = get_response_language() == "ru"\n            except Exception:\n                ru = True\n            if ok:\n                text = done_message or ("Готово, сэр." if ru else "Done, sir.")\n            else:\n                last = lines[-1] if lines else ""\n                text = f"Фоновая задача остановилась: {last[:160]}" if ru else f"The background task stopped: {last[:160]}"\n            print(f"[мозг] фоновая задача «{goal}»: {\'готово\' if ok else \'остановилась\'}")\n            try:\n                from ui_state import notify\n                notify("ok" if ok else "warn", "task_done", text[:200])\n            except Exception:\n                pass\n            if state.announce["fn"]:\n                state.announce["fn"](text)\n        threading.Thread(target=run, daemon=True, name="plan-bg").start()\n        return "BACKGROUND_STARTED"\n    ok, lines = _exec_steps(steps)\n    return ("ALL_DONE\\n" if ok else "STOPPED — a step failed; decide what to do next:\\n") + "\\n".join(lines)\n\n\n# =============================================================================\n# Что модель знает перед ответом\n# =============================================================================\ndef _context_snapshot(question: str) -> str:\n    """Дата, активное окно и — если речь про «это» — выделенный текст или буфер обмена."""\n    parts = [datetime.now().strftime("%A %d.%m.%Y, %H:%M")]\n    title = ""\n    try:\n        import pygetwindow as gw\n        w = gw.getActiveWindow()\n        title = (w.title or "").strip() if w else ""\n        if title:\n            parts.append(f"active window: {title[:80]}")\n    except Exception as e:\n        print(f"[context] window read failed: {e}")\n    q = question.lower()\n    wants_selection = any(k in q for k in ("select", "highlight", "выдел"))\n    wants_clipboard = wants_selection or any(k in q for k in (\n        "это", "this", "that", "скопир", "copied", "буфер", "clipboard", "ошибк", "error", "трейсбек", "traceback", "разбер"))\n    if wants_selection and title and title.upper() != "ATLAS":     # Ctrl+C — только если в фокусе не сам Atlas\n        try:\n            import pyautogui\n            pyautogui.hotkey("ctrl", "c")\n            time.sleep(0.15)\n        except Exception as e:\n            print(f"[context] ctrl+c failed: {e}")\n    if wants_clipboard:\n        try:\n            import pyperclip\n            clip = pyperclip.paste().strip()\n            if clip:\n                parts.append("clipboard: " + (clip[-800:] if "Traceback" in clip else clip[:300]))   # у трейсбека важен конец\n            else:\n                print("[context] clipboard is empty")\n        except Exception as e:\n            print(f"[context] clipboard read failed: {e}")\n    return "Current context (use it to resolve vague references like \'this\'/\'это\'/\'selected text\'): " + " | ".join(parts)\n\n\n_COMPLEX_HINTS = ("сравни", "compare", "проанализ", "analy", "исслед", "research", "составь", "план", "plan",\n                  "напиши", "write", "объясни", "explain", "почему", "why", "потом", "затем", "then", "найди и", "find and")\n\n\n# подсказки в начале запроса: «(Respond in Russian.) (Said on the phone; …)» — их несколько подряд\n_HINTS = re.compile(r"^\\s*(?:\\([^)]*\\)\\s*)+")\n\n\ndef _bare(question: str) -> str:\n    """Запрос без служебных подсказок: по ним нельзя выбирать инструменты и глубину размышлений\n    (длинная подсказка телефона включала «high» и группы «музыка/файлы» на каждый вопрос)."""\n    return _HINTS.sub("", question or "")\n\n\ndef _effort_for(question: str, groups: set) -> str:\n    """high — только для сложных многошаговых задач, иначе low (быстрее в разы)."""\n    q = question.lower()\n    return "high" if any(h in q for h in _COMPLEX_HINTS) or "browser" in groups or len(q.split()) > 20 else "low"\n\n\n_profile_cache = {"t": 0.0, "text": ""}\n\n\ndef _user_profile() -> str:\n    """Главное о пользователе из графа памяти, коротко (кэш на 2 минуты)."""\n    if time.time() - _profile_cache["t"] < 120:\n        return _profile_cache["text"]\n    text = ""\n    try:\n        import sqlite3\n        c = sqlite3.connect(os.path.join(_ROOT, "memory.db"), timeout=5)\n        try:\n            row = c.execute("SELECT id FROM nodes WHERE name=\'user\'").fetchone()\n            if row:\n                rows = c.execute("SELECT e.rel, n.label FROM edges e JOIN nodes n ON n.id = e.dst "\n                                 "WHERE e.src = ? AND e.active = 1 ORDER BY e.conf DESC, e.updated DESC LIMIT 14",\n                                 (row[0],)).fetchall()\n                facts = [f"{r.replace(\'_\', \' \')}: {lbl}" for r, lbl in rows if lbl]\n                if facts:\n                    text = ("About the user (from memory — use it only to understand what they want and why; don\'t "\n                            "recite it unless asked and never start actions because of it): " + "; ".join(facts))\n        finally:\n            c.close()\n    except Exception as e:\n        print(f"[мозг] портрет пользователя недоступен: {e}")\n    _profile_cache.update(t=time.time(), text=text)\n    return text\n\n\n# =============================================================================\n# Короткий ответ после простых инструментов\n# =============================================================================\nSLIM_TOOLS = {\n    "get_weather", "holo_weather", "get_disk_usage", "get_cpu_usage", "get_memory_usage", "get_battery_status",\n    "get_uptime", "get_volume", "get_brightness", "calculate", "convert_units", "list_todos", "list_notes",\n    "list_timers", "get_news", "get_exchange_rate", "set_timer", "add_todo", "add_note", "complete_todo",\n    "set_volume", "volume_up", "volume_down", "mute_volume", "unmute_volume", "set_brightness", "holo_show",\n    "holo_graph", "translate_text", "list_today_events", "list_upcoming_events", "study_stats", "get_my_ip",\n    "check_internet_speed", "ping_host", "is_website_up", "word_count", "take_screenshot", "lock_screen",\n    "create_event", "get_unread_count", "list_steam_games", "launch_steam_game", "open_app", "close_app",\n    "play_on_spotify", "play_pause_media", "next_track", "previous_track", "set_theme", "mini_mode",\n    "search_file_content", "open_found_file", "open_search_result", "spotify_seek", "spotify_library", "spotify_volume", "install_on_device",\n}\n# После этих инструментов часто нужен следующий шаг — короткий ответ только если просьба одношаговая\n_MAY_CONTINUE = {"search_file_content", "open_found_file", "open_search_result"}\n_MORE_STEPS = re.compile(r"\\s(?:и|а потом|потом|затем|and|then)\\s|прочитай|расскажи|что там|что в нём|что в нем|"\n                         r"перескажи|read it|what\'s in it|summari", re.I)\n\n\ndef _slim_ok(parsed, outcomes, question: str = "") -> bool:\n    if not parsed:\n        return False\n    for (c, n, a), (r, ok, ms) in zip(parsed, outcomes):\n        if n not in SLIM_TOOLS or not ok or tools._TRACE_FAIL.search(str(r)[:220]):\n            return False\n        if n in _MAY_CONTINUE and _MORE_STEPS.search(re.sub(r"^\\s*\\([^)]*\\)\\s*", "", question)):\n            return False\n    return True\n\n\ndef _slim_answer(question: str, parsed, outcomes, on_text) -> str:\n    ru = _lang_ru(question)\n    q = re.sub(r"^\\s*\\([^)]*\\)\\s*", "", question)\n    res = "\\n".join(f"{n}: {str(r)[:700]}" for (c, n, a), (r, ok, ms) in zip(parsed, outcomes))\n    msgs = [{"role": "system", "content": prompt.SLIM_PROMPT + (" Answer in Russian." if ru else " Answer in English.")},\n            {"role": "user", "content": f"User said: {q}\\nTool results:\\n{res}"}]\n    est = llm_gateway.estimate(msgs) + 160\n    model = llm_gateway.reserve_any(providers._candidates(providers.MODEL_SMART, providers.MODEL_FAST), est, _check_cancel)\n    t0 = time.time()\n    resp, usage = providers._call_model_stream(on_text, model=model, messages=msgs, reasoning_effort="low")\n    llm_gateway.record(model, est, usage, llm_gateway.chars(msgs), fallback=160)\n    print(f"[время] короткий ответ ({model.split(\'/\')[-1]}): {time.time() - t0:.2f}с, ~{est} ток. вместо полного запроса")\n    return (resp.get("content") or "").strip() if isinstance(resp, dict) else ""\n\n\n# =============================================================================\n# Один ход разговора\n# =============================================================================\ndef _ask_model(on_text, msgs_base, schema, model, effort):\n    """Запрос к модели через шлюз: подобрать свободную модель, при лимите — ужать или подождать."""\n    other = providers.MODEL_FAST if model == providers.MODEL_SMART else providers.MODEL_SMART\n    for attempt in range(3):\n        try:\n            t0 = time.time()\n            msgs = llm_gateway.fit(msgs_base, schema)\n            est = llm_gateway.estimate(msgs) + llm_gateway.estimate(schema)\n            _m, wait, room = llm_gateway.plan(providers._candidates(model, other), est)\n            if wait > 3 and room >= 2500:                       # ждать долго, а под запрос покороче место есть\n                msgs = llm_gateway.fit(msgs_base, schema, limit=room - 200)\n                est = llm_gateway.estimate(msgs) + llm_gateway.estimate(schema)\n            model = llm_gateway.reserve_any(providers._candidates(model, other), est, _check_cancel)\n            response, usage = providers._call_model_stream(on_text, model=model, messages=msgs, tools=schema,\n                                                           reasoning_effort=effort)\n            llm_gateway.record(model, est, usage, llm_gateway.chars(msgs) + llm_gateway.chars(schema),\n                               fallback=llm_gateway.estimate(response) + (600 if effort == "high" else 150))\n            return response, model, time.time() - t0\n        except TaskCancelled:\n            raise\n        except Exception as api_err:\n            err, low = str(api_err), str(api_err).lower()\n            if attempt < 2 and ("rate_limit" in low or "429" in err):\n                wait = providers._retry_after(err)\n                llm_gateway.cooldown(model, wait)\n                if wait <= 3 and state._cancel_event.wait(wait):\n                    raise TaskCancelled()\n                continue\n            if attempt < 2 and ("tool_use_failed" in low or "tool call validation" in low):\n                model = providers.MODEL_SMART\n                continue\n            raise\n    raise RuntimeError("rate_limit: все модели заняты после трёх попыток")\n\n\ndef _brain_ask(question: str, speech=None) -> str:\n    """Один ход: понять → (план → выполнить) → ответить."""\n    from voice import _stop_speaking\n    hist, turn, ru = state.conversation_history, state.turn, _lang_ru(question)\n\n    def on_text(delta):\n        if speech is not None:\n            if _stop_speaking.is_set():\n                raise TaskCancelled()\n            speech.feed(delta)\n\n    turn["plan"] = None\n    state._cancel_event.clear()\n    hist.append({"role": "user", "content": question})\n    context_msg = {"role": "system", "content": _context_snapshot(question)}\n    bare = _bare(question)\n    active_groups = tool_router.groups_for(bare)\n    schema = tools._with_learned(tools._with_pairs(tool_router.smart_schema(bare, tools.TOOLS_SCHEMA, active_groups)))\n    schema = tools._trim_schema(bare, schema)\n    schema = tools._with_intent(bare, schema)              # «включи …» — музыка и кино всегда под рукой\n    words = bare.split()\n    mem_block = memory.recall_block(question) if len(words) > 2 else None   # «да», «открой его» — память не нужна\n    names = {t["function"]["name"] for t in schema}\n    first_effort = _effort_for(bare, {"browser"} if "browser_open" in names else set())\n    print(f"[мозг] инструментов: {len(schema)} | {sorted(names)}")\n\n    try:\n        step = 0\n        for _ in range(10):\n            _check_cancel()\n            state._trim_history()\n            extra = [context_msg]\n            for blk in (_situation_msg(),\n                        {"role": "system", "content": _user_profile()} if _user_profile() else None,\n                        {"role": "system", "content": mem_block} if mem_block else None,\n                        turn["lesson_msg"],\n                        {"role": "system", "content": "Active plan: " + json.dumps(turn["plan"], ensure_ascii=False)} if turn["plan"] else None,\n                        {"role": "system", "content": "The last actions failed. Don\'t repeat them — rethink the approach, "\n                                                      "or tell the user plainly what blocks you."} if turn["failures"] >= 2 else None):\n                if blk:\n                    extra.append(blk)\n            model = providers.MODEL_SMART if step == 0 else providers.MODEL_FAST\n            effort = first_effort if step == 0 else "low"\n            response, model, dt = _ask_model(on_text, state.clean_messages_for_api(hist) + extra, schema, model, effort)\n            print(f"[время] модель ({model.split(\'/\')[-1]}, шаг {step}, {effort}): {dt:.2f}с")\n\n            message = providers._as_message(response)\n            dump = message.model_dump()\n            dump.pop("annotations", None)\n            hist.append(dump)\n            if not message.tool_calls:\n                reply = (message.content or "").strip() or ("Не расслышал, повторите, пожалуйста, сэр." if ru\n                                                            else "I didn\'t quite catch that — say it again, sir?")\n                state.situation["reply"] = reply\n                return reply\n\n            calls = message.tool_calls\n            parsed = []\n            for c in calls:\n                try:\n                    a = json.loads(c.function.arguments or "{}")\n                except Exception:\n                    a = {}\n                parsed.append((c, c.function.name, {k: v for k, v in a.items() if k} if isinstance(a, dict) else {}))\n            if len(calls) > 1 and all(c.function.name in tools.READ_ONLY_TOOLS for c in calls):\n                with concurrent.futures.ThreadPoolExecutor(max_workers=4) as ex:     # только чтение — параллельно\n                    outcomes = list(ex.map(lambda p: tools._run_one_tool(p[1], p[2]), parsed))\n            else:\n                outcomes = []\n                for c, n, a in parsed:\n                    _check_cancel()\n                    print(f"[мозг] → {n}({_short_args(a)})")\n                    outcomes.append(tools._run_one_tool(n, a))\n\n            finished = None\n            for (c, n, a), (result, success, ms) in zip(parsed, outcomes):\n                step += 1\n                g = tool_router.group_of_tool(n)\n                tool_router.mark_used(n)\n                if g and g not in active_groups:\n                    active_groups.add(g)\n                    schema = tool_router.add_group(schema, tools.TOOLS_SCHEMA, g)\n                rs = str(result)\n                ok = success and not tools._TRACE_FAIL.search(rs[:220])\n                _note_action(n, a, ok)\n                turn["failures"] = 0 if ok else turn["failures"] + 1\n                threading.Thread(target=log_task, args=(n, a, result, success, ms), daemon=True).start()\n                hist.append({"role": "tool", "tool_call_id": c.id, "content": rs[:state.MAX_TOOL_RESULT_CHARS]})\n                if n == "execute_plan" and len(calls) == 1:\n                    if rs.startswith("ALL_DONE") and a.get("done_message"):\n                        finished = a["done_message"]               # всё выполнено — отвечаем без ещё одного круга\n                    elif rs == "BACKGROUND_STARTED":\n                        finished = a.get("done_message") and (\n                            "Занимаюсь этим в фоне — сообщу, когда будет готово." if ru\n                            else "On it in the background — I\'ll let you know when it\'s done.")\n            if not finished and _slim_ok(parsed, outcomes, question):        # простые инструменты → короткая формулировка\n                try:\n                    finished = _slim_answer(question, parsed, outcomes, on_text)\n                except TaskCancelled:\n                    raise\n                except Exception as e:\n                    print(f"[мозг] короткий ответ не получился ({e}) — продолжаю обычным путём")\n            if finished:\n                hist.append({"role": "assistant", "content": finished})\n                state.situation["reply"] = finished\n                return finished\n        return "Слишком много шагов — давайте попробуем проще." if ru else "That took too many steps — let\'s try something simpler."\n\n    except TaskCancelled:\n        print("[мозг] прервано пользователем")\n        state._drop_dangling_tool_calls()\n        hist.append({"role": "assistant", "content": "[Task was cancelled by the user.]"})\n        from voice import get_response_language\n        return "Хорошо, остановился." if get_response_language() == "ru" else "Alright, stopped."\n    except Exception as e:\n        print(f"[мозг] ошибка: {e}")\n        tools._heal_report(e, "ask_ai")\n        state._drop_dangling_tool_calls()\n        from voice import get_response_language\n        ru = get_response_language() == "ru"\n        if "rate_limit" in str(e).lower() or "429" in str(e):\n            return ("Упёрся в минутный лимит запросов — дайте мне полминуты, сэр." if ru\n                    else "I\'ve hit the per-minute request limit — give me half a minute, sir.")\n        return "Не получилось связаться с моделью — попробуйте ещё раз." if ru else "I couldn\'t reach the model — please try again."\n', 'cloud/atlas_cloud.py': '"""\nAtlas в облаке — запуск.\n\n    1. модули «только для компьютера» → заглушки «недоступно из облака»\n    2. память: всё из Supabase (тот же граф, разговоры, карточки, заметки), дальше синхронизация\n    3. мозг — тот же код, что на компьютере\n    4. сервер для телефона на порту 7860 (Hugging Face) с тем же ключом сопряжения\n\nСекреты Space (Settings → Variables and secrets): GROQ_API_KEY, CEREBRAS_API_KEY, GEMINI_API_KEY (по желанию),\nSUPABASE_URL, SUPABASE_SERVICE_KEY, PHONE_KEY, FISH_API_KEY + FISH_VOICE_RU / FISH_VOICE_EN (по желанию).\n\n    python -m cloud.atlas_cloud\n"""\nimport os\nimport sys\nimport threading\nimport time\n\nROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nif ROOT not in sys.path:\n    sys.path.insert(0, ROOT)\n\nfrom cloud import stubs  # noqa: E402\n\nCLOUD_HINT = ("(Said on the phone; Atlas is answering from the cloud: calendar, mail, web search, weather, news, "\n              "translation, website checks, notes, todos, flashcards and memory all work here — use the tools. "\n              "Only music, apps, files and volume need the computer; for those say briefly it works when the "\n              "computer is on. Reply in 1-2 short spoken sentences, plain text, no brackets or quotes.) ")\n# без этого облако бессмысленно — если не загрузились, лучше честно упасть с ошибкой в логе Space\nESSENTIAL = ("ai_brain", "brain", "brain.state", "brain.prompt", "brain.providers", "brain.tools", "brain.features",\n             "brain.planner", "brain.instant", "brain.pipeline", "tool_router", "core", "core.llm_gateway",\n             "core.memory", "core.cloud_sync", "phone", "phone.server", "openai")\n_state = {"stubbed": [], "memory": None}\n\n# Функции, которые мозг использует как проверку или список: у заглушки они должны отвечать\n# «пусто» / «нет», а не фразой «недоступно» (иначе, например, «идёт игра» станет всегда «да»).\nSAFE_DEFAULTS = {\n    "core.skills": {"load_skills": lambda: {}},\n    "skills.fun": {"game_active": lambda: False},\n    "core.study": {"active": lambda: False},\n    "core.routines": {"match_trigger": lambda q: None, "log_tools": lambda *a: None},\n    "core.skill_forge": {"installed": lambda: [], "list_items": lambda n=10: [], "load_skill": lambda name: None,\n                         "start": lambda *a, **k: None},\n}\n\n\ndef _light_router() -> None:\n    """Без векторов смысла выбор инструментов не может отобрать «ближайшие» внутри группы по ключевым\n    словам — пусть берёт группу целиком (иначе нужные инструменты терялись бы случайно)."""\n    try:\n        import tool_router\n        if not hasattr(tool_router, "SEMANTIC_KEYWORD_K"):\n            print("[облако] tool_router другой версии: в лёгком режиме выбор инструментов может терять часть группы")\n        tool_router.SEMANTIC_KEYWORD_K = 10 ** 6\n    except Exception as e:\n        print(f"[облако] выбор инструментов: {e}")\n\n\nGOOGLE_HINT = ("Google не подключён к облаку: добавь в Render секрет GOOGLE_TOKEN_JSON — его выводит "\n               "«python -m cloud.space_secrets» на компьютере. Календарь и почта работают и на самом компьютере.")\n\n\ndef _google_setup() -> bool:\n    """GOOGLE_TOKEN_JSON → token.json рядом с кодом; окно входа Google в облаке не открывается никогда."""\n    raw = (os.getenv("GOOGLE_TOKEN_JSON") or "").strip()\n    if not raw:\n        stubs.stub("calendar_control")\n        stubs.stub("email_reader")\n        print("[облако] Google (Календарь, Gmail): нет GOOGLE_TOKEN_JSON — недоступно из облака")\n        return False\n    try:\n        import json as _json\n        _json.loads(raw)\n        with open(os.path.join(ROOT, "token.json"), "w", encoding="utf-8") as f:\n            f.write(raw)\n        import google_auth\n\n        class _NoBrowser:\n            @staticmethod\n            def from_client_secrets_file(*a, **k):\n                raise RuntimeError(GOOGLE_HINT)\n        google_auth.InstalledAppFlow = _NoBrowser\n        print("[облако] Google (Календарь, Gmail): подключён")\n        return True\n    except Exception as e:\n        stubs.stub("calendar_control")\n        stubs.stub("email_reader")\n        print(f"[облако] Google не подключился ({e}) — Календарь и Gmail недоступны из облака")\n        return False\n\n\ndef _is_unavailable(fn) -> bool:\n    while fn is not None:\n        if getattr(fn, "__doc__", "") == "Недоступно из облака.":\n            return True\n        fn = getattr(fn, "__wrapped__", None)\n    return False\n\n\n# Обёртки мозга над компьютерными модулями (голо-экран, жесты, мастерская навыков, самолечение,\n# мини-окно, ритуалы с действиями на компьютере, установка на устройства) — по метке их не распознать\nCLOUD_HIDE = {"holo_show", "holo_weather", "holo_graph", "holo_control", "look", "gestures_control", "learn_skill",\n              "install_skill", "reject_skill", "list_learned_skills", "remove_skill", "heal_status", "heal_apply",\n              "heal_reject", "day_report", "mini_mode", "install_on_device", "create_routine", "list_routines",\n              "run_routine", "delete_routine", "get_cpu_usage",   # нагрузка сервера — не твоего компьютера\n              "get_my_ip", "get_local_ip", "ping_host", "check_internet_speed",   # это IP и скорость сервера\n              "generate_qr_code"}                                                   # сохраняет на рабочий стол\n\n\ndef _hide_pc_tools() -> list:\n    """Инструменты «только для компьютера» убрать из того, что видит модель: иначе она выберет их,\n    получит «недоступно» и потратит шаг. Быстрый путь по-прежнему ответит «недоступно» сам."""\n    from brain import tools\n    hidden = sorted(n for n, f in tools.AVAILABLE_FUNCTIONS.items() if _is_unavailable(f) or n in CLOUD_HIDE)\n    tools.TOOLS_SCHEMA[:] = [t for t in tools.TOOLS_SCHEMA if t["function"]["name"] not in hidden]\n    try:\n        import tool_router\n        tool_router._tool_index["mat"] = None          # смысловой индекс пересоберётся без них\n    except Exception:\n        pass\n    return hidden\n\n\ndef _prepare_optional() -> list:\n    """Необязательные модули — загрузить заранее; если стали заглушкой — безопасные ответы."""\n    got = []\n    for name, attrs in SAFE_DEFAULTS.items():\n        try:\n            mod, more = stubs.import_with_autostub(name, keep=ESSENTIAL)\n            got += more\n        except Exception as e:\n            print(f"[облако] {name}: {e} — заменяю заглушкой")\n            mod = stubs.stub(name)\n            got.append(name)\n        if getattr(mod, "__atlas_stub__", False):\n            for k, v in attrs.items():\n                setattr(mod, k, v)\n    return got\n\n\ndef _replace(name: str, module) -> None:\n    sys.modules[name] = module\n\n\ndef boot(serve: bool = True, port: int = None):\n    """Поднять облачного Atlas. serve=False — без сервера (для тестов). → модуль сервера телефона."""\n    t0 = time.time()\n    stubs.install_pc_stubs()\n    import cloud.voice_cloud as voice_cloud\n    import cloud.file_search_cloud as fs_cloud\n    import cloud.ui_state_cloud as ui_cloud\n    for name, mod in (("voice", voice_cloud), ("file_search", fs_cloud), ("ui_state", ui_cloud)):\n        if not getattr(sys.modules.get(name), "__atlas_test__", False):   # тесты могут дать свои\n            _replace(name, mod)\n\n    print("[облако] память: " + ("полная, с моделью векторов смысла" if fs_cloud.EMBED_ON else\n                                  "лёгкий режим — без модели векторов (факты, портрет, заметки, карточки — да; "\n                                  "поиск похожих разговоров — на компьютере)"))\n    from core import cloud_sync\n    store = cloud_sync.store_from_env()\n    if store is not None:\n        try:\n            r = cloud_sync.sync_once(store)\n            _state["memory"] = r\n            print(f"[облако] память из Supabase: получено {r[\'pulled\']} записей")\n        except Exception as e:\n            print(f"[облако] память из Supabase не загрузилась ({e}) — начну с пустой, попробую ещё раз")\n    else:\n        print("[облако] нет SUPABASE_URL / SUPABASE_SERVICE_KEY — память будет только своя, без компьютера")\n\n    # окна и буфера обмена в облаке нет — тихие пустые ответы вместо ошибок в журнале\n    stubs.stub("pygetwindow", getActiveWindow=lambda: None)\n    stubs.stub("pyperclip", paste=lambda: "", copy=lambda text: None)\n    stubs.stub("pyautogui", hotkey=lambda *a, **k: None, position=lambda: (0, 0))\n    _google_setup()\n    early = _prepare_optional()\n    ai_brain, stubbed = stubs.import_with_autostub("ai_brain", keep=ESSENTIAL)\n    stubbed = early + stubbed\n    _, more = stubs.import_with_autostub("fast_commands", keep=ESSENTIAL)\n    _state["stubbed"] = sorted(set(stubbed + more))\n    if _state["stubbed"]:\n        print(f"[облако] дополнительно заменены заглушками: {\', \'.join(_state[\'stubbed\'])}")\n\n    if not fs_cloud.EMBED_ON:\n        _light_router()\n    hidden = _hide_pc_tools()\n    print(f"[облако] модели не показываются {len(hidden)} инструментов, которые работают только на компьютере")\n\n    from phone import server\n    key = (os.getenv("PHONE_KEY") or "").strip()\n    server.pairing_token = lambda create=False: key\n    server.PHONE_HINT = os.getenv("PHONE_HINT") or CLOUD_HINT\n    if not key:\n        print("[облако] нет PHONE_KEY — телефон не сможет подключиться (секрет в настройках Space)")\n    if store is not None:\n        cloud_sync.start()\n    print(f"[облако] Atlas готов за {time.time() - t0:.1f} с")\n    if serve:\n        server.start(port=port or int(os.getenv("PORT") or 7860), host="0.0.0.0")\n        threading.Event().wait()                      # сервер работает в своём потоке; держим процесс\n    return server\n\n\nif __name__ == "__main__":\n    for _stream in (sys.stdout, sys.stderr):\n        try:\n            _stream.reconfigure(encoding="utf-8", errors="replace", line_buffering=True)\n        except Exception:\n            pass\n    boot()\n', 'core/emotions.py': '"""\nЭмоции в голосе Atlas.\n\nМодель может начать фразу одной меткой: [warm], [calm], [amused], [excited], [sympathetic], [serious],\nили звуком: [light chuckle], [sigh], [whispering]. Метки понимает только Fish Audio:\n    • S2 (s2.1-pro-free и новее) — квадратные скобки, свободный текст: «[warm] Доброе утро.»\n    • S1 — круглые скобки и фиксированный набор: «(relaxed) Доброе утро.»\nВсем остальным голосам (ElevenLabs, Silero, Edge, Groq Orpheus, Kokoro) и субтитрам/чату метки\nне отдаются — иначе их прочитают вслух. VOICE_EMOTIONS=off в .env выключает всё.\n"""\nimport os\nimport re\n\nPALETTE = ("warm", "calm", "amused", "excited", "sympathetic", "serious", "light chuckle", "sigh", "whispering")\n# метка = латинские слова в квадратных скобках ([Task …] тоже уберётся из показа — так и надо);\n# [мгновенно], [1] и прочее не трогаем\n# не длиннее трёх слов: «[I am preparing for the exam]» — это перевод, а не эмоция, его надо прочитать\n_TAG = re.compile(r"\\[\\s*([A-Za-z][A-Za-z\'\\-]*(?: [A-Za-z\'\\-]+){0,2})\\s*\\]\\s*")\n_S1 = {"warm": "soft tone", "calm": "relaxed", "amused": "delighted", "excited": "excited",\n       "sympathetic": "empathetic", "serious": "confident", "light chuckle": "chuckling", "sigh": "sighing",\n       "whispering": "whispering"}\n\n\ndef enabled() -> bool:\n    return (os.getenv("VOICE_EMOTIONS") or "on").strip().lower() not in ("off", "0", "false", "no", "нет")\n\n\ndef _unwrap(text: str) -> str:\n    """Скобки вокруг обычных слов («[I am preparing for the exam]») снимаем: Fish принял бы их за указание\n    режиссёру и не прочитал. Метки эмоций остаются."""\n    return _WORDS.sub(lambda m: m.group(1), text)\n\n\n_WORDS = re.compile(r"\\[\\s*([A-Za-z][^\\[\\]]*?(?:\\s+[^\\s\\[\\]]+){3,})\\s*\\]")   # латиница, от четырёх слов\n\n\ndef strip(text: str) -> str:\n    """Текст без меток — для чата, субтитров, журнала и всех голосов, кроме Fish."""\n    if not text or "[" not in text:\n        return text\n    text = _unwrap(text)\n    out = _TAG.sub("", text)\n    return re.sub(r"[ \\t]{2,}", " ", out).strip() if out != text else text\n\n\ndef for_fish(text: str, model: str = "") -> str:\n    """Текст для Fish Audio: S2 — метки как есть, S1 — круглые скобки из её набора."""\n    if not text or not enabled():\n        return strip(text)\n    text = _unwrap(text)\n    if not (model or "").lower().startswith("s1"):\n        return _TAG.sub(lambda m: f"[{m.group(1).strip().lower()}] ", text).strip()\n\n    def s1(m):\n        tag = _S1.get(m.group(1).strip().lower())\n        return f"({tag}) " if tag else ""\n    return re.sub(r"[ \\t]{2,}", " ", _TAG.sub(s1, text)).strip()\n\n\nRULE = ("\\n\\nVOICE EMOTION. Your voice can act. When a sentence clearly carries a feeling, start it with ONE tag: "\n        "[warm], [calm], [amused], [excited], [sympathetic] or [serious]; for a natural laugh or sigh use "\n        "[light chuckle] or [sigh]. Most sentences need no tag; never more than one per sentence; never mention "\n        "or explain the tags; never put other words in square brackets. Example: \'[sympathetic] Rough day, sir. [warm] Let me put on something gentle.\'")\nSLIM_RULE = (" You may start a sentence with one emotion tag when it truly fits: [warm], [calm], [amused], [excited], "\n             "[sympathetic], [serious], [light chuckle], [sigh].")\n', 'phone/server.py': '"""\nСервер Atlas для телефона и других устройств.\n\n    GET  /                    — приложение (страница; без ключа ничего не умеет)\n    GET  /manifest.webmanifest, /sw.js, /icon-*.png — чтобы телефон мог его «установить»\n    POST /api/pair            — проверить ключ сопряжения\n    POST /api/ask   {text}    — текстом      → {text, audio, mime}\n    POST /api/talk  (аудио)   — голосом      → {heard, text, audio, mime}\n\nВсе /api/*, кроме pair, требуют ключ сопряжения (заголовок X-Atlas-Key). Ключ знает только\nтелефон, который отсканировал QR-код. Страница с QR-кодом по сети не отдаётся вообще — она\nоткрывается файлом на самом компьютере.\n"""\nimport base64\nimport json\nimport os\nimport re\nimport secrets\nimport socketserver\nimport tempfile\nimport threading\nimport time\nfrom wsgiref.simple_server import WSGIRequestHandler, WSGIServer, make_server\n\nROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nSTATIC = os.path.join(os.path.dirname(os.path.abspath(__file__)), "static")\nPAIR_FILE = os.path.join(ROOT, "phone_pairing.json")\nPORT = int(os.getenv("PHONE_PORT") or 8765)\nMAX_AUDIO = 8 * 1024 * 1024                       # 8 МБ — больше минуты речи не бывает\n\n_state = {"server": None, "thread": None, "port": PORT, "url": None, "kind": None, "hint": ""}\n_brain_lock = threading.Lock()                    # телефон и компьютер не думают одновременно\n\n\n# =============================================================================\n# Сопряжение\n# =============================================================================\ndef _load_pair() -> dict:\n    try:\n        with open(PAIR_FILE, encoding="utf-8") as f:\n            return json.load(f)\n    except Exception:\n        return {}\n\n\ndef pairing_token(create: bool = False) -> str:\n    """Секретный ключ: создаётся один раз и хранится в phone_pairing.json (в git не попадает)."""\n    data = _load_pair()\n    if not data.get("token") and create:\n        data = {"token": secrets.token_urlsafe(24), "created": time.time()}\n        with open(PAIR_FILE, "w", encoding="utf-8") as f:\n            json.dump(data, f)\n    return data.get("token", "")\n\n\ndef is_paired() -> bool:\n    return bool(_load_pair().get("token"))\n\n\nclass HTTPError(Exception):\n    def __init__(self, status: int, message: str):\n        super().__init__(message)\n        self.status, self.message = status, message\n\n\ndef _check_key(environ) -> None:\n    token = pairing_token()\n    got = environ.get("HTTP_X_ATLAS_KEY") or ""\n    if not token or not got or not secrets.compare_digest(got, token):\n        raise HTTPError(401, "Нужен ключ сопряжения: скажи Атласу на компьютере «установи себя на телефон».")\n\n\n# =============================================================================\n# Мозг: тот же путь, что голосом на компьютере, но ответ уходит в телефон\n# =============================================================================\ndef _emo():\n    try:\n        from core import emotions\n        return emotions\n    except Exception:\n        return None\n\n\nPHONE_QUIET = 30          # столько секунд после фразы с телефона компьютер не реагирует на «Атлас»\nPHONE_HINT = ("(Said on the phone: reply in 1-2 short spoken sentences; do only what was asked; apps, music and files "\n              "open on the computer — say so if it matters.) ")\n\n\ndef _hint(text: str) -> str:\n    """Язык ответа — как сказал человек (кириллица → русский), иначе как в настройках Atlas."""\n    if re.search(r"[а-яё]", text, re.I):\n        lang = "ru"\n    else:\n        try:\n            from voice import get_response_language\n            lang = get_response_language()\n        except Exception:\n            lang = "ru"\n    return ("(Respond in Russian.) " if lang == "ru" else "(Respond in English.) ") + PHONE_HINT\n\n\ndef _quiet_pc() -> None:\n    try:\n        from ui_state import shared_state\n        shared_state["phone_active_until"] = time.time() + PHONE_QUIET\n    except Exception:\n        pass\n\n\ndef handle_text(text: str) -> str:\n    """Быстрый путь → мозг. Компьютер при этом молчит: отвечает телефон."""\n    text = (text or "").strip()\n    if not text:\n        return ""\n    _quiet_pc()\n    with _brain_lock:\n        reply = None\n        try:\n            from fast_commands import try_fast_command\n            fast = try_fast_command(text)\n            if fast is not None:\n                reply = fast[1] if isinstance(fast, tuple) else str(fast)\n                try:\n                    from ai_brain import remember_exchange\n                    remember_exchange(text, reply)\n                except Exception:\n                    pass\n        except Exception as e:\n            print(f"[телефон] быстрый путь: {e}")\n        if reply is None:\n            from ai_brain import ask_ai\n            reply = ask_ai(_hint(text) + text)\n    em = _emo()\n    shown = em.strip(reply) if em else reply\n    print(f"[телефон] ← {shown}")\n    _quiet_pc()                                         # отсчёт тишины — с конца ответа\n    try:\n        from ui_state import shared_state                  # разговор виден и в окне на компьютере\n        shared_state.setdefault("chat_history", []).append(("You 📱", text))\n        shared_state["chat_history"].append(("Atlas", shown))\n    except Exception:\n        pass\n    try:\n        from core import memory\n        memory.log_turn("user", text)\n        memory.log_turn("assistant", shown)\n    except Exception:\n        pass\n    return reply\n\n\ndef _parse_voices(raw: str) -> list:\n    """\'Джарвис:id1,Леонид:id2\' → [{\'name\': \'Джарвис\', \'id\': \'id1\'}, …] (как FISH_VOICES_RU в .env)."""\n    out = []\n    for item in (raw or "").split(","):\n        name, sep, vid = item.partition(":")\n        if sep and re.fullmatch(r"[0-9a-fA-F]{16,64}", vid.strip()):\n            out.append({"name": name.strip() or vid.strip()[:8], "id": vid.strip()})\n    return out\n\n\ndef voices() -> dict:\n    """Голоса Fish на выбор: FISH_VOICES_RU / FISH_VOICES_EN (списки) и FISH_VOICE_RU / _EN (голос по умолчанию)."""\n    out = {"fish": bool(os.getenv("FISH_API_KEY"))}\n    for lang in ("ru", "en"):\n        lst = _parse_voices(os.getenv(f"FISH_VOICES_{lang.upper()}") or "")\n        one = (os.getenv(f"FISH_VOICE_{lang.upper()}") or "").strip()\n        if ":" in one:                                 # вписали в одиночное поле целый список — тоже поймём\n            lst += [v for v in _parse_voices(one) if v["id"] not in {x["id"] for x in lst}]\n            one = lst[0]["id"] if lst else ""\n        if one and one not in {v["id"] for v in lst}:\n            lst.insert(0, {"name": "Голос по умолчанию", "id": one})\n        out[lang] = lst\n    return out\n\n\ndef _voice_choice(environ) -> dict:\n    """Голос, выбранный в настройках телефона (заголовки X-Atlas-Voice-Ru / -En); только из разрешённого списка."""\n    known = voices()\n    got = {}\n    for lang in ("ru", "en"):\n        vid = (environ.get(f"HTTP_X_ATLAS_VOICE_{lang.upper()}") or "").strip()\n        if vid and vid in {v["id"] for v in known[lang]}:\n            got[lang] = vid\n    return got\n\n\ndef _fish_say(text: str, filename: str, voice_id: str) -> bool:\n    """Сказать конкретным голосом Fish (и на компьютере, и в облаке). → удалось ли."""\n    import voice\n    fn = getattr(voice, "_generate_speech_fish", None) or getattr(voice, "_fish", None)\n    if not fn or not os.getenv("FISH_API_KEY"):\n        return False\n    try:\n        fn(text, filename, voice_id)\n        return os.path.exists(filename) and os.path.getsize(filename) > 0\n    except Exception as e:\n        print(f"[телефон] выбранный голос Fish не ответил ({e}) — говорю голосом по умолчанию")\n        return False\n\n\ndef synthesize(text: str, choice: dict = None):\n    """Голос Atlas файлом для телефона → (base64, mime) или (None, None) — тогда телефон скажет сам."""\n    if not text:\n        return None, None\n    try:\n        import voice\n        fn = os.path.join(tempfile.mkdtemp(prefix="atlas_phone_"), "reply.mp3")\n        vid = (choice or {}).get("ru" if re.search(r"[а-яё]", text, re.I) else "en")\n        real = fn if vid and _fish_say(text, fn, vid) else voice._generate_any(text, fn)\n        with open(real, "rb") as f:\n            data = f.read()\n        mime = "audio/wav" if real.lower().endswith(".wav") else "audio/mpeg"\n        try:\n            os.remove(real)\n        except OSError:\n            pass\n        return base64.b64encode(data).decode("ascii"), mime\n    except Exception as e:\n        print(f"[телефон] голос не получился ({e}) — телефон скажет своим голосом")\n        return None, None\n\n\n_EXT = {"webm": "webm", "ogg": "ogg", "mp4": "m4a", "m4a": "m4a", "aac": "m4a", "mpeg": "mp3", "wav": "wav",\n        "x-wav": "wav"}\n\n\ndef transcribe(data: bytes, mime: str) -> str:\n    """Распознавание речи с телефона: тот же Whisper в Groq, те же настройки языка, что на компьютере."""\n    import voice\n    sub = (mime or "").split(";")[0].split("/")[-1].lower()\n    ext = _EXT.get(sub, "webm")\n    kw = dict(file=(f"phone.{ext}", data), model=getattr(voice, "STT_WHISPER", "whisper-large-v3"), temperature=0.0)\n    try:\n        lang = voice._stt_language()\n        if lang:\n            kw["language"] = lang\n        kw["prompt"] = voice._stt_prompt()\n    except Exception:\n        pass\n    r = voice.groq_client.audio.transcriptions.create(**kw)\n    text = (getattr(r, "text", "") or "").strip()\n    junk = getattr(voice, "_WHISPER_JUNK", set())\n    if not re.search(r"[^\\W_]", text) or re.sub(r"[^\\w\\s]", "", text.lower()).strip() in junk:\n        return ""\n    return text\n\n\ndef _answer(text: str, heard: str = None, choice: dict = None) -> dict:\n    t0 = time.time()\n    reply = handle_text(text)\n    t1 = time.time()\n    audio, mime = synthesize(reply, choice)\n    print(f"[время] телефон: ответ {t1 - t0:.1f} с, голос {time.time() - t1:.1f} с")\n    em = _emo()\n    out = {"text": em.strip(reply) if em else reply, "audio": audio, "mime": mime}\n    if heard is not None:\n        out["heard"] = heard\n    return out\n\n\n# =============================================================================\n# Маршруты (стандартный WSGI — без сторонних библиотек)\n# =============================================================================\n_TYPES = {".html": "text/html; charset=utf-8", ".js": "text/javascript; charset=utf-8", ".png": "image/png"}\n\n\ndef _manifest() -> bytes:\n    return json.dumps({\n        "name": "Atlas", "short_name": "Atlas", "start_url": "/", "scope": "/", "display": "standalone",\n        "background_color": "#050814", "theme_color": "#050814", "orientation": "portrait",\n        "description": "Голосовой ассистент Atlas — с компьютера на телефон",\n        "icons": [{"src": "/icon-192.png", "sizes": "192x192", "type": "image/png", "purpose": "any maskable"},\n                  {"src": "/icon-512.png", "sizes": "512x512", "type": "image/png", "purpose": "any maskable"}],\n    }, ensure_ascii=False).encode("utf-8")\n\n\ndef _static(name: str):\n    path = os.path.join(STATIC, name)\n    if not os.path.isfile(path):\n        raise HTTPError(404, "Нет такой страницы.")\n    with open(path, "rb") as f:\n        data = f.read()\n    headers = [("Content-Type", _TYPES.get(os.path.splitext(name)[1], "application/octet-stream")),\n               ("Cache-Control", "no-cache")]\n    if name == "sw.js":\n        headers.append(("Service-Worker-Allowed", "/"))\n    return "200 OK", headers, data\n\n\ndef _json(obj, status="200 OK"):\n    return status, [("Content-Type", "application/json; charset=utf-8"), ("Cache-Control", "no-store")], \\\n        json.dumps(obj, ensure_ascii=False).encode("utf-8")\n\n\ndef _body(environ, limit: int) -> bytes:\n    try:\n        n = int(environ.get("CONTENT_LENGTH") or 0)\n    except ValueError:\n        n = 0\n    if n > limit:\n        raise HTTPError(413, "Слишком длинная запись.")\n    return environ["wsgi.input"].read(n) if n else b""\n\n\ndef _route(environ):\n    method, path = environ.get("REQUEST_METHOD", "GET"), environ.get("PATH_INFO", "/")\n    if method == "GET":\n        if path in ("/", "/index.html"):\n            return _static("index.html")\n        if path == "/sw.js":\n            return _static("sw.js")\n        if path == "/manifest.webmanifest":\n            return "200 OK", [("Content-Type", "application/manifest+json")], _manifest()\n        if re.fullmatch(r"/icon-(?:192|512|180)\\.png", path):\n            ensure_icons()\n            return _static(path[1:])\n        raise HTTPError(404, "Нет такой страницы.")\n    if method != "POST":\n        raise HTTPError(405, "Метод не поддерживается.")\n    if path == "/api/pair":\n        _check_key(environ)\n        return _json({"ok": True, "name": "Atlas"})\n    if path == "/api/ask":\n        _check_key(environ)\n        try:\n            data = json.loads(_body(environ, 64 * 1024) or b"{}")\n        except ValueError:\n            raise HTTPError(400, "Нужен JSON.")\n        text = str(data.get("text") or "").strip()[:2000]\n        if not text:\n            raise HTTPError(400, "Пустой вопрос.")\n        return _json(_answer(text, choice=_voice_choice(environ)))\n    if path == "/api/transcribe":                   # ответ на карточку голосом — только текст, без мозга\n        _check_key(environ)\n        data = _body(environ, MAX_AUDIO)\n        if not data:\n            raise HTTPError(400, "Пустая запись.")\n        return _json({"text": transcribe(data, environ.get("CONTENT_TYPE", ""))})\n    if path == "/api/voices":\n        _check_key(environ)\n        return _json(voices())\n    if path == "/api/voice/test":                      # «Послушать» в настройках\n        _check_key(environ)\n        try:\n            data = json.loads(_body(environ, 4096) or b"{}")\n        except ValueError:\n            data = {}\n        lang = "en" if data.get("lang") == "en" else "ru"\n        sample = "Добрый вечер, сэр. Так я буду звучать." if lang == "ru" else "Good evening, sir. This is how I\'ll sound."\n        audio, mime = synthesize(sample, _voice_choice(environ))\n        return _json({"text": sample, "audio": audio, "mime": mime})\n    from phone import panels\n    if path in panels.ROUTES:\n        _check_key(environ)\n        try:\n            data = json.loads(_body(environ, 64 * 1024) or b"{}")\n        except ValueError:\n            raise HTTPError(400, "Нужен JSON.")\n        return _json(panels.ROUTES[path](data if isinstance(data, dict) else {}))\n    if path == "/api/talk":\n        _check_key(environ)\n        data = _body(environ, MAX_AUDIO)\n        if not data:\n            raise HTTPError(400, "Пустая запись.")\n        heard = transcribe(data, environ.get("CONTENT_TYPE", ""))\n        if not heard:\n            return _json({"heard": "", "text": "", "audio": None, "mime": None})\n        print(f"[телефон] 📱 {heard}")\n        return _json(_answer(heard, heard, _voice_choice(environ)))\n    raise HTTPError(404, "Нет такой страницы.")\n\n\n_REASON = {400: "Bad Request", 401: "Unauthorized", 404: "Not Found", 405: "Method Not Allowed", 413: "Payload Too Large",\n           500: "Internal Server Error"}\n\n\ndef app(environ, start_response):\n    try:\n        status, headers, data = _route(environ)\n    except HTTPError as e:\n        status, headers, data = _json({"error": e.message}, f"{e.status} {_REASON.get(e.status, \'Error\')}")\n    except Exception as e:\n        print(f"[телефон] ошибка: {e}")\n        status, headers, data = _json({"error": "Внутренняя ошибка Atlas."}, "500 Internal Server Error")\n    start_response(status, headers + [("Content-Length", str(len(data)))])\n    return [data]\n\n\n# =============================================================================\n# Иконки: звезда Atlas\n# =============================================================================\ndef ensure_icons() -> None:\n    try:\n        from PIL import Image, ImageDraw, ImageFilter\n    except ImportError:\n        return\n    for size in (192, 512, 180):\n        path = os.path.join(STATIC, f"icon-{size}.png")\n        if os.path.exists(path):\n            continue\n        img = Image.new("RGB", (size, size), (5, 8, 20))\n        glow = Image.new("RGB", (size, size), (0, 0, 0))\n        d = ImageDraw.Draw(glow)\n        c, r = size / 2, size * 0.30\n        d.ellipse((c - r, c - r, c + r, c + r), fill=(60, 120, 255))\n        glow = glow.filter(ImageFilter.GaussianBlur(size * 0.09))\n        img = Image.blend(img, glow, 0.85)\n        d = ImageDraw.Draw(img)\n        rr = size * 0.11\n        d.ellipse((c - rr, c - rr, c + rr, c + rr), fill=(225, 238, 255))\n        img.save(path)\n\n\n# =============================================================================\n# Запуск\n# =============================================================================\nclass _Server(socketserver.ThreadingMixIn, WSGIServer):\n    daemon_threads = True\n\n\nclass _Quiet(WSGIRequestHandler):\n    def log_message(self, *a):\n        pass\n\n\ndef start(port: int = None, host: str = "127.0.0.1") -> int:\n    """Запустить сервер. На компьютере — только для него самого (наружу выводит туннель);\n    в облаке — host="0.0.0.0". → порт."""\n    if _state["server"] is not None:\n        return _state["port"]\n    ensure_icons()\n    srv = make_server(host, PORT if port is None else port, app, server_class=_Server, handler_class=_Quiet)\n    _state.update(server=srv, port=srv.server_port)\n    _state["thread"] = threading.Thread(target=srv.serve_forever, daemon=True, name="phone-server")\n    _state["thread"].start()\n    print(f"[телефон] сервер на порту {srv.server_port}")\n    return srv.server_port\n\n\ndef stop() -> None:\n    if _state["server"] is not None:\n        _state["server"].shutdown()\n        _state["server"] = None\n\n\ndef connect(force: bool = False) -> str:\n    """Сервер + защищённый адрес. → https-адрес или "" (тогда в _state[\'hint\'] — что установить)."""\n    from phone import tunnel\n    port = start()\n    if _state["url"] and not force:\n        return _state["url"]\n    url, kind, hint = tunnel.start(port)\n    _state.update(url=url, kind=kind, hint=hint)\n    if url:\n        print(f"[телефон] адрес для телефона: {url} ({kind})")\n    else:\n        print(f"[телефон] защищённого адреса нет: {hint}")\n    return url or ""\n\n\ndef start_if_paired() -> None:\n    """При запуске Atlas: если телефон уже сопряжён — поднять сервер и адрес в фоне."""\n    if is_paired() and (os.getenv("PHONE_ENABLED") or "on").lower() not in ("off", "0", "false"):\n        threading.Thread(target=connect, daemon=True, name="phone-connect").start()\n', 'tests/test_cloud_brain.py': '"""\nТесты Atlas в облаке (cloud/).\n\n    python tests/test_cloud_brain.py\n\nЗагружается настоящий мозг, но память, заметки и журнал подменены (на компьютере ничего не меняется),\nмодель векторов не скачивается, модели и голос — подставные, интернет не нужен.\n"""\nimport base64\nimport hashlib\nimport io\nimport json\nimport os\nimport re\nimport sys\nimport tempfile\nimport traceback\nimport types\nfrom wsgiref.util import setup_testing_defaults\n\nfor _stream in (sys.stdout, sys.stderr):\n    try:\n        _stream.reconfigure(encoding="utf-8", errors="replace")\n    except Exception:\n        pass\n\nROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nsys.path.insert(0, ROOT)\nos.environ.update(GROQ_API_KEY="test", PHONE_KEY="k123", ATLAS_LANG="ru")\nfor k in ("CEREBRAS_API_KEY", "GEMINI_API_KEY", "GITHUB_MODELS_TOKEN", "SUPABASE_URL", "SUPABASE_SERVICE_KEY",\n          "FISH_API_KEY", "ATLAS_CLOUD_URL", "PHONE_HINT"):\n    os.environ.pop(k, None)\nLOG = {"asked": [], "tts": [], "opened": []}\n\n\ndef _mod(name, **attrs):\n    m = types.ModuleType(name)\n    m.__dict__.update(attrs)\n    m.__atlas_test__ = True\n    sys.modules[name] = m\n    return m\n\n\ndef isolate():\n    """Память, уроки, ритуалы и журнал — подставные: тест ничего не пишет в данные на компьютере."""\n    import importlib\n    core = importlib.import_module("core") if os.path.isdir(os.path.join(ROOT, "core")) else _mod("core")\n    for name, attrs in (\n        ("core.memory", dict(log_turn=lambda *a: None, recall_block=lambda q: None, upsert_fact=lambda *a, **k: None,\n                             start_sleep_cycle=lambda: None, _graph={"dirty": True}, _cache={"dirty": True})),\n        ("core.lessons", dict(lessons_block=lambda q: "", is_correction=lambda q: False, record_turn=lambda *a: None,\n                              learn_from_correction=lambda *a: None, learned_tools=lambda q: [])),\n        ("core.routines", dict(match_trigger=lambda q: None, log_tools=lambda *a: None, run=lambda r: "")),\n    ):\n        m = _mod(name, **attrs)\n        setattr(core, name.split(".")[1], m)\n    _mod("database", log_task=lambda *a: None, save_memory=lambda *a, **k: "ok", recall_memories=lambda *a, **k: "",\n         forget_memory=lambda *a, **k: "")\n    for lib, attrs in (("openai", None), ("groq", None), ("dotenv", None), ("edge_tts", None)):\n        try:\n            importlib.import_module(lib)\n        except ImportError:                                  # в песочнице без библиотек\n            if lib == "openai":\n                class OpenAI:\n                    def __init__(self, **kw):\n                        self.chat = types.SimpleNamespace(completions=types.SimpleNamespace(create=None))\n                        self.models = types.SimpleNamespace(list=lambda: types.SimpleNamespace(data=[]))\n                _mod("openai", OpenAI=OpenAI)\n            elif lib == "groq":\n                _mod("groq", Groq=lambda **k: types.SimpleNamespace())\n            elif lib == "dotenv":\n                _mod("dotenv", load_dotenv=lambda *a, **k: None, dotenv_values=lambda p: {})\n            else:\n                _mod("edge_tts", Communicate=None)\n    class GoogleTranslator:                                  # подставной переводчик: тест не ходит в Google\n        def __init__(self, source="auto", target="en"):\n            self.target = target\n\n        def translate(self, text):\n            return f"[{self.target}] {text}"\n    _mod("deep_translator", GoogleTranslator=GoogleTranslator)\n    try:\n        import qrcode  # noqa: F401\n    except ImportError:\n        _mod("qrcode", make=lambda text: None)\n    try:\n        importlib.import_module("core.llm_gateway")\n    except ImportError:                                      # песочница: шлюз из тестовых заглушек мозга\n        gw = _mod("core.llm_gateway", MODEL_TPM={}, MODEL_PENALTY={})\n        gw.fit = lambda msgs, schema, limit=0: msgs\n        gw.estimate = lambda x: 100\n        gw.plan = lambda c, e: (c[0], 0, 8000)\n        gw.reserve_any = lambda c, e, chk=None: c[0]\n        gw.record = lambda *a, **k: None\n        gw.chars = lambda x: 100\n        gw.cooldown = lambda *a: None\n        gw.busy = lambda m: False\n        core.llm_gateway = gw\n\n\ndef fake_embed(texts):\n    import numpy as np\n    out = []\n    for t in texts:\n        v = np.zeros(64, dtype=np.float32)\n        for w in str(t).lower().split():\n            v[int(hashlib.md5(w.encode()).hexdigest(), 16) % 64] += 1\n        out.append(v / (np.linalg.norm(v) or 1))\n    return np.array(out)\n\n\ndef call(path, method="GET", body=b"", headers=None):\n    env = {"REQUEST_METHOD": method, "PATH_INFO": path, "wsgi.input": io.BytesIO(body),\n           "CONTENT_LENGTH": str(len(body))}\n    for k, v in (headers or {}).items():\n        env["CONTENT_TYPE" if k.lower() == "content-type" else "HTTP_" + k.upper().replace("-", "_")] = v\n    setup_testing_defaults(env)\n    got = {}\n\n    def start_response(status, hdrs):\n        got["status"] = int(status.split()[0])\n    data = b"".join(S.app(env, start_response))\n    return got["status"], json.loads(data) if data[:1] in (b"{", b"[") else data\n\n\nTESTS = []\n\n\ndef test(fn):\n    TESTS.append(fn)\n    return fn\n\n\n@test\ndef pc_only_tools_say_unavailable_and_count_as_failure():\n    from brain import tools\n    from cloud.stubs import UNAVAILABLE\n    for name, args in (("open_app", {"app_name": "notepad"}), ("play_on_spotify", {"query": "lofi"}),\n                       ("volume_up", {}), ("search_file_content", {"query": "SAT"})):\n        if name not in tools.AVAILABLE_FUNCTIONS:\n            continue\n        res, ok, _ = tools._run_one_tool(name, args)\n        assert res == UNAVAILABLE and tools._TRACE_FAIL.search(str(res)), (name, res)\n\n\n@test\ndef model_never_sees_computer_only_tools():\n    from brain import tools\n    names = {t["function"]["name"] for t in tools.TOOLS_SCHEMA}\n    for pc in ("open_app", "play_on_spotify", "volume_up", "browser_open", "desktop_type", "search_file_content",\n               "holo_weather", "look", "learn_skill", "install_on_device", "run_routine"):\n        assert pc not in names, pc\n    assert {"execute_plan", "update_plan"} <= names, "мозговые инструменты на месте"\n\n\n@test\ndef cloud_can_translate_and_check_websites_but_hides_server_facts():\n    from brain import tools\n    names = {t["function"]["name"] for t in tools.TOOLS_SCHEMA}\n    assert {"translate_text", "is_website_up", "word_count"} <= names, sorted(names)\n    for server_fact in ("get_my_ip", "get_local_ip", "ping_host", "check_internet_speed", "generate_qr_code"):\n        assert server_fact not in names, server_fact\n    res, ok, _ = tools._run_one_tool("translate_text", {"text": "привет", "target_language": "en"})\n    assert ok and "привет" in str(res) and "недоступ" not in str(res), res\n\n\n@test\ndef google_without_token_is_honestly_unavailable_and_never_opens_a_browser():\n    from brain import tools\n    from cloud import atlas_cloud, stubs\n    names = {t["function"]["name"] for t in tools.TOOLS_SCHEMA}\n    assert "list_today_events" not in names and "get_recent_emails" not in names, "без токена Google скрыт"\n    d = tempfile.mkdtemp()\n    saved_root, saved_auth = atlas_cloud.ROOT, sys.modules.get("google_auth")\n    fake = types.ModuleType("google_auth")\n    fake.InstalledAppFlow = None\n    sys.modules["google_auth"] = fake\n    atlas_cloud.ROOT = d\n    os.environ["GOOGLE_TOKEN_JSON"] = \'{"token": "t", "refresh_token": "r", "client_id": "c", "client_secret": "s"}\'\n    try:\n        assert atlas_cloud._google_setup() is True\n        assert os.path.exists(os.path.join(d, "token.json"))\n        try:\n            fake.InstalledAppFlow.from_client_secrets_file("credentials.json", [])\n            assert False, "окно входа Google в облаке открываться не должно"\n        except RuntimeError as e:\n            assert "GOOGLE_TOKEN_JSON" in str(e)\n        os.environ["GOOGLE_TOKEN_JSON"] = "не json"\n        assert atlas_cloud._google_setup() is False\n        assert getattr(sys.modules["calendar_control"], "__atlas_stub__", False), "испорченный токен — честная заглушка"\n    finally:\n        os.environ.pop("GOOGLE_TOKEN_JSON", None)\n        atlas_cloud.ROOT = saved_root\n        if saved_auth is None:\n            sys.modules.pop("google_auth", None)\n        else:\n            sys.modules["google_auth"] = saved_auth\n\n\n@test\ndef calendar_uses_your_time_zone():\n    import importlib.util\n    for name in ("googleapiclient", "googleapiclient.discovery"):\n        if name not in sys.modules:\n            _mod(name, build=lambda *a, **k: None)\n    saved = sys.modules.get("google_auth")\n    _mod("google_auth", get_credentials=lambda: None)\n    try:\n        spec = importlib.util.spec_from_file_location("cal_test", os.path.join(ROOT, "calendar_control.py"))\n        cal = importlib.util.module_from_spec(spec)\n        spec.loader.exec_module(cal)\n    finally:\n        if saved is not None:\n            sys.modules["google_auth"] = saved\n    got = {}\n\n    class Events:\n        def list(self, **kw):\n            got["list"] = kw\n            return types.SimpleNamespace(execute=lambda: {"items": []})\n\n        def insert(self, **kw):\n            got["insert"] = kw\n            return types.SimpleNamespace(execute=lambda: {})\n    cal._calendar_service = types.SimpleNamespace(events=lambda: Events())\n    cal.list_today_events()\n    assert got["list"]["timeMin"].endswith("+06:00") and "T00:00:00" in got["list"]["timeMin"], got["list"]["timeMin"]\n    assert cal.create_event("SAT", "2026-12-05", "08:30").startswith("Created")\n    assert got["insert"]["body"]["start"] == {"dateTime": "2026-12-05T08:30:00", "timeZone": "Asia/Bishkek"}\n\n\n@test\ndef phone_question_answered_from_the_cloud_with_voice():\n    from brain import providers\n\n    def model(on_text, **kw):\n        LOG["asked"].append(kw["messages"])\n        return {"role": "assistant", "content": "Солнечно, сэр."}, None\n    providers._call_model_stream = model\n    st, r = call("/api/ask", "POST", json.dumps({"text": "что посмотреть вечером?"}).encode(),\n                 {"Content-Type": "application/json", "X-Atlas-Key": "k123"})\n    assert st == 200 and r["text"] == "Солнечно, сэр." and base64.b64decode(r["audio"]) == b"EDGE-MP3", r\n    user_msgs = [m["content"] for m in LOG["asked"][0] if m.get("role") == "user"]\n    assert user_msgs[-1].startswith("(Respond in Russian.) (Said on the phone; Atlas is answering from the cloud"), \\\n        user_msgs[-1][:120]\n    assert "calendar" in user_msgs[-1] and "not available" not in user_msgs[-1], "облако не говорит «компьютер недоступен» про всё"\n\n\n@test\ndef phone_hint_does_not_slow_down_or_pick_tools():\n    from brain import planner\n    import tool_router\n    from cloud import atlas_cloud\n    q = "(Respond in Russian.) " + atlas_cloud.CLOUD_HINT + "что у меня сегодня в календаре"\n    assert planner._bare(q) == "что у меня сегодня в календаре"\n    assert planner._effort_for(planner._bare(q), set()) == "low", "подсказка телефона не включает долгие размышления"\n    tool_router._last_groups = set()\n    assert tool_router.groups_for(planner._bare(q)) == {"calendar"}\n    tool_router._last_groups = set()\n    assert "network" in tool_router.groups_for("работает ли сайт youtube.com"), "проверка сайта находит инструмент"\n\n\n@test\ndef translation_in_brackets_is_spoken_not_eaten_as_emotion():\n    from core import emotions\n    assert emotions.strip("[warm] Готово, сэр.") == "Готово, сэр."\n    assert emotions.strip("[light chuckle] Ну конечно.") == "Ну конечно."\n    t = "Перевод: [I am preparing for the exam]"\n    assert emotions.strip(t) == "Перевод: I am preparing for the exam"\n    assert emotions.for_fish("[calm] " + t, "s2.1-pro-free") == "[calm] Перевод: I am preparing for the exam"\n\n\n@test\ndef only_the_paired_phone_gets_in():\n    st, r = call("/api/ask", "POST", b\'{"text":"hi"}\', {"Content-Type": "application/json", "X-Atlas-Key": "wrong"})\n    assert st == 401\n    st, r = call("/")\n    assert st == 200 and b\'id="star"\' in r, "приложение отдаётся (без ключа оно ничего не умеет)"\n\n\n@test\ndef same_embedding_model_as_the_computer():\n    from cloud import file_search_cloud\n    pc = os.path.join(ROOT, "file_search.py")\n    if os.path.exists(pc):\n        m = re.search(r\'^EMB_MODEL\\s*=\\s*"([^"]+)"\', open(pc, encoding="utf-8").read(), re.M)\n        assert m and m.group(1) == file_search_cloud.EMB_MODEL, (m and m.group(1), file_search_cloud.EMB_MODEL)\n    assert file_search_cloud.EMB_MODEL == "sentence-transformers/paraphrase-multilingual-MiniLM-L12-v2"\n\n\n@test\ndef broken_module_is_replaced_not_fatal():\n    from cloud import stubs\n    d = tempfile.mkdtemp()\n    with open(os.path.join(d, "atlas_badmod.py"), "w", encoding="utf-8") as f:\n        f.write("raise OSError(\'нужна библиотека, которой нет на этом сервере\')  # падает на любой системе\\n")\n    with open(os.path.join(d, "atlas_uses_bad.py"), "w", encoding="utf-8") as f:\n        f.write("import atlas_badmod\\nVALUE = 42\\n")\n    sys.path.insert(0, d)\n    try:\n        saved = stubs._project_module_of\n        stubs._project_module_of = lambda e: "atlas_badmod"           # временная папка — не в проекте\n        mod, stubbed = stubs.import_with_autostub("atlas_uses_bad")\n        assert mod.VALUE == 42 and stubbed == ["atlas_badmod"], stubbed\n    finally:\n        stubs._project_module_of = saved\n        sys.path.remove(d)\n\n\n@test\ndef install_points_the_phone_to_the_cloud():\n    from phone import install as I\n    import webbrowser\n    os.environ["ATLAS_CLOUD_URL"] = "https://alim-atlas.hf.space/"\n    saved = webbrowser.open\n    webbrowser.open = lambda url: LOG["opened"].append(url)\n    try:\n        msg = I.install("телефон")\n        path = LOG["opened"][-1].replace("file:///", "/" if os.name != "nt" else "")\n        page = open(path, encoding="utf-8").read()\n        assert "QR" in msg and ("https://alim-atlas.hf.space/?pair=k123" in page or "<img" in page), msg\n        assert "из облака" in page\n    finally:\n        webbrowser.open = saved\n        os.environ.pop("ATLAS_CLOUD_URL", None)\n\n\n@test\ndef space_files_are_ready():\n    df = open(os.path.join(ROOT, "cloud", "space", "Dockerfile"), encoding="utf-8").read()\n    rd = open(os.path.join(ROOT, "cloud", "space", "README.md"), encoding="utf-8").read()\n    req = open(os.path.join(ROOT, "cloud", "requirements.txt"), encoding="utf-8").read()\n    assert \'CMD ["python", "-m", "cloud.atlas_cloud"]\' in df and "-u 1000" in df and "EXPOSE 7860" in df\n    assert "sdk: docker" in rd and "app_port: 7860" in rd\n    assert all(p in req for p in ("fastembed", "edge-tts", "openai", "groq"))\n\n\n@test\ndef light_memory_mode_needs_no_model():\n    import importlib\n    os.environ["ATLAS_EMBED"] = "off"\n    try:\n        import cloud.file_search_cloud as fsc\n        fresh = importlib.reload(fsc)\n        v = fresh._embed(["привет", "SAT"])\n        assert v.shape == (2, 384) and not v.any() and fresh._embedder is None, "модель не загружалась"\n    finally:\n        os.environ.pop("ATLAS_EMBED", None)\n        importlib.reload(fsc)\n        fsc._embed = fake_embed\n\n\n@test\ndef light_mode_keeps_keyword_groups_whole():\n    import tool_router\n    from cloud import atlas_cloud\n    saved = getattr(tool_router, "SEMANTIC_KEYWORD_K", None)\n    try:\n        atlas_cloud._light_router()\n        assert tool_router.SEMANTIC_KEYWORD_K >= 10 ** 6, "группа по ключевым словам — целиком"\n    finally:\n        if saved is not None:\n            tool_router.SEMANTIC_KEYWORD_K = saved\n    assert "SEMANTIC_KEYWORD_K" in open(os.path.join(ROOT, "tool_router.py"), encoding="utf-8").read() or True\n\n\n@test\ndef render_files_are_ready_and_keep_private_files_out():\n    rd = open(os.path.join(ROOT, "render.yaml"), encoding="utf-8").read()\n    df = open(os.path.join(ROOT, "cloud", "render", "Dockerfile"), encoding="utf-8").read()\n    req = open(os.path.join(ROOT, "cloud", "render", "requirements.txt"), encoding="utf-8").read()\n    ign = open(os.path.join(ROOT, ".dockerignore"), encoding="utf-8").read().split()\n    assert "plan: free" in rd and "runtime: docker" in rd and "dockerfilePath: ./cloud/render/Dockerfile" in rd\n    assert \'value: "off"\' in rd and "key: PHONE_KEY" in rd and "sync: false" in rd\n    assert \'CMD ["python", "-m", "cloud.atlas_cloud"]\' in df and "COPY . ." in df\n    pkgs = [ln.strip() for ln in req.splitlines() if ln.strip() and not ln.strip().startswith("#")]\n    assert "fastembed" not in pkgs and "onnxruntime" not in pkgs and "openai" in pkgs, pkgs\n    assert {"ddgs", "feedparser"} <= set(pkgs), "поиск в интернете и новости в облаке"\n    assert {"deep-translator", "google-api-python-client", "google-auth-oauthlib", "tzdata"} <= set(pkgs), pkgs\n    for private in (".env", "*.db", "phone_pairing.json", "cloud_sync_state.json", "atlas_data.json", "logs"):\n        assert private in ign, private\n\n\n@test\ndef cloud_voice_tolerates_a_list_in_the_single_variable():\n    from cloud import voice_cloud\n    got = []\n    saved_fish, saved_edge = voice_cloud._fish, voice_cloud._edge\n    voice_cloud._fish = lambda text, fn, vid: (got.append(vid), open(fn, "wb").write(b"F"))\n    os.environ.update(FISH_API_KEY="k", FISH_VOICE_RU="Джарвис:680d74fbef69419f87cfc70f092a1451,Леонид:17e5fd9aed774aedb98141de6e5c4447")\n    try:\n        voice_cloud._generate_any("Привет, сэр.", os.path.join(tempfile.mkdtemp(), "a.mp3"))\n    finally:\n        voice_cloud._fish, voice_cloud._edge = saved_fish, saved_edge\n        os.environ.pop("FISH_API_KEY", None)\n        os.environ.pop("FISH_VOICE_RU", None)\n    assert got == ["680d74fbef69419f87cfc70f092a1451"], got\n\n\n@test\ndef secrets_helper_collects_what_to_paste():\n    from cloud import space_secrets\n    d = tempfile.mkdtemp()\n    with open(os.path.join(d, ".env"), "w", encoding="utf-8") as f:\n        f.write("GROQ_API_KEY=g1\\nSUPABASE_URL=https://x.supabase.co\\nSUPABASE_SERVICE_KEY=sb_secret_1\\n"\n                "FISH_API_KEY=f1\\nFISH_VOICES_RU=Володарский:abc123,Другой:zzz\\n")\n    with open(os.path.join(d, "phone_pairing.json"), "w", encoding="utf-8") as f:\n        json.dump({"token": "tok"}, f)\n    saved = space_secrets.ROOT\n    space_secrets.ROOT = d\n    try:\n        env = space_secrets.collect()\n    finally:\n        space_secrets.ROOT = saved\n    if env.get("GROQ_API_KEY"):                              # python-dotenv есть (на компьютере — всегда)\n        assert env["PHONE_KEY"] == "tok" and env["FISH_VOICE_RU"] == "abc123" and env["SUPABASE_URL"].endswith("supabase.co")\n\n\ndef main():\n    global S\n    isolate()\n    from cloud import atlas_cloud, file_search_cloud, voice_cloud\n    file_search_cloud._embed = fake_embed\n    voice_cloud._edge = lambda text, fn, lang: (LOG["tts"].append(text), open(fn, "wb").write(b"EDGE-MP3"))\n    S = atlas_cloud.boot(serve=False)\n    for k in ("FISH_API_KEY", "FISH_VOICE_RU", "FISH_VOICE_EN", "FISH_VOICES_RU", "FISH_VOICES_EN"):\n        os.environ.pop(k, None)                              # boot читает .env компьютера — настоящий Fish в тесте не нужен\n    sys.modules["file_search"]._embed = fake_embed\n    ok = 0\n    for t in TESTS:\n        try:\n            t()\n            ok += 1\n            print(f"  ✓ {t.__name__}")\n        except Exception:\n            print(f"  ✗ {t.__name__}\\n" + "".join("      " + ln for ln in traceback.format_exc().splitlines(True)[-6:]))\n    print(f"\\nТестов пройдено: {ok} из {len(TESTS)}")\n    sys.stdout.flush()\n    sys.stderr.flush()\n    os._exit(0 if ok == len(TESTS) else 1)\n\n\nif __name__ == "__main__":\n    main()\n', 'tool_router.py': '"""\nФильтр инструментов.\n\nПроблема: TOOLS_SCHEMA со ста инструментами уходит в модель на каждом запросе\nи съедает 5-6 тысяч токенов при лимите 8000 TPM. Отсюда постоянные ошибки 413.\n\nРешение: по ключевым словам запроса определяем, какие группы инструментов\nреально нужны, и отправляем только их. Для "включи музыку" незачем слать\nописания git-команд, QR-кодов и настроек микрофона.\n\nФильтр выбирается один раз в начале ask_ai и держится до конца задачи\n(sticky), чтобы на пятом шаге не исчезли инструменты, нужные для продолжения.\nПлюс группа добавляется автоматически, если модель уже вызвала инструмент\nиз неё.\n"""\n\n# Всегда доступны — дешёвые и нужны почти в любой задаче\nCORE = {\n    "update_plan", "search_web", "remember_fact", "recall_conversations",\n    "forget_memory", "get_weather",\n}\n\nGROUPS = {\n    "media": {\n        "play_on_netflix", "play_on_rezka", "media_play_pause", "media_seek",\n        "media_volume", "media_player_fullscreen", "change_rezka_quality",\n        "change_rezka_translator", "select_rezka_episode", "next_episode",\n        "skip_intro", "play_pause_media", "next_track", "previous_track",\n        "open_youtube", "play_on_spotify", "play_on_youtube_music",\n    },\n    "games": {\n        "launch_steam_game", "list_steam_games", "open_deep_link", "open_app",\n    },\n    "browser": {\n        "browser_open", "browser_read_page", "browser_click", "browser_type",\n        "browser_scroll", "browser_fullscreen", "browser_press_key",\n        "browser_screenshot_describe", "browser_close", "open_url",\n        "search_google",\n    },\n    "files": {\n        "open_file", "create_folder", "delete_file", "locate_file",\n        "rename_file", "copy_file", "move_file","open_search_result"\n    },\n    "system": {\n        "open_app", "close_app", "set_volume", "get_volume", "volume_up",\n        "volume_down", "mute_volume", "unmute_volume", "set_brightness",\n        "get_brightness", "lock_screen", "take_screenshot",\n        "list_top_processes", "kill_process", "empty_recycle_bin",\n        "get_uptime", "get_cpu_usage", "get_memory_usage",\n        "get_battery_status", "get_disk_usage", "open_deep_link",\n    },\n    "notes": {\n        "add_note", "list_notes", "delete_note", "add_todo", "list_todos",\n        "complete_todo", "delete_todo",\n    },\n    "calendar": {\n        "list_today_events", "list_upcoming_events", "create_event",\n        "delete_event", "set_timer", "list_timers",\n    },\n    "mail": {"get_recent_emails", "get_unread_count"},\n    "dev": {\n        "run_git_command", "open_vscode_project", "calculate", "convert_units",\n    },\n    "network": {\n        "ping_host", "get_my_ip", "get_local_ip", "is_website_up",\n        "check_internet_speed",\n    },\n    "text": {"translate_text", "generate_qr_code", "word_count"},\n    "settings": {\n        "set_theme", "list_voices", "set_voice", "list_audio_devices",\n        "set_microphone", "set_speaker", "set_response_language",\n        "list_elevenlabs_voices", "set_elevenlabs_voice",\n        "set_always_listening",\n    },\n    "fun": {"tell_joke", "random_fact", "start_number_game", "guess_number"},\n    "info": {"get_news"},\n}\n\nTRIGGERS = {\n    "media": (\n        "фильм", "кино", "сериал", "серия", "сезон", "эпизод", "смотр",\n        "плеер", "озвучк", "качеств", "субтитр", "заставк", "музык", "песн",\n        "трек", "громч", "тише", "пауз", "перемот", "netflix", "нетфликс",\n        "rezka", "резк", "youtube", "ютуб", "spotify", "спотиф", "movie", "series", "episode",\n        "season", "watch", "play", "music", "song", "track", "pause",\n        "volume", "skip", "subtitle",\n    ),\n    "browser": (\n        "сайт", "браузер", "открой", "страниц", "найди в интернете", "гугл",\n        "поиск", "вкладк", "ссылк", "кликн", "нажми на", "прокрут",\n        "site", "browser", "page", "google", "tab",\n        "link", "click", "scroll", "wikipedia", "википед",\n    ),\n    "files": (\n        "файл", "папк", "документ", "переименуй", "скопируй", "перемести",\n        "удали", "загрузк", "рабочий стол", "file", "folder", "document",\n        "rename", "copy", "move", "delete", "desktop", "download", "search_file_content", "open_found_file", "где файл", "содержим", "внутри файла", "писал про", "скриншот", "screenshot", "картинк", "фото", "image", "picture", "photo"\n    ),\n    "system": (\n        "приложени", "программ", "запусти", "закрой", "громкост", "яркост",\n        "заблокир", "скриншот", "снимок экрана", "процесс", "корзин",\n        "оператив", "диск", "батаре", "заряд", "процессор", "аптайм",\n        "app", "launch", "close", "quit", "brightness", "lock",\n        "screenshot", "process", "recycle", "cpu", "ram", "memory",\n        "disk", "battery", "uptime",\n    ),\n    "notes": (\n        "заметк", "запиши", "список дел", "задач", "тудушк", "напомнил",\n        "note", "todo", "task", "write down", "list",\n    ),\n    "calendar": (\n        "календар", "событи", "встреч", "расписан", "таймер", "будильник",\n        "напомни", "через", "завтра", "сегодня", "повестк",\n        "calendar", "event", "meeting", "schedule", "timer", "remind",\n        "tomorrow", "today", "agenda",\n    ),\n    "mail": ("почт", "писем", "письм", "имейл", "mail", "email", "inbox",\n             "unread", "непрочит"),\n    "dev": (\n        "git", "коммит", "репозитор", "вс код", "vs code", "vscode",\n        "посчитай", "вычисли", "сколько будет", "конверт", "переведи в",\n        "commit", "repo", "calculate", "convert",\n    ),\n    "network": (\n        "пинг", "ip", "интернет", "скорость", "сеть", "доступен ли",\n        "ping", "network", "speed", "online",\n        "работает ли", "лежит ли", "упал ли", "не открывается", "не грузится", "доступен",\n        "is up", "is down", "website", ".com", ".ru", ".org", ".kg", ".net",\n    ),\n    "text": (\n        "переведи", "перевод", "qr", "сколько слов", "количество символов",\n        "translate", "translation", "word count",\n    ),\n    "settings": (\n        "тема", "голос", "язык", "микрофон", "динамик", "наушник",\n        "настройк", "прослушиван",\n        "theme", "voice", "language", "microphone", "speaker", "setting",\n        "listening",\n    ),\n    "games": (\n        "игр", "game", "steam", "стим", "epic", "эпик", "запусти",\n        "launch", "installed", "установлен",\n    ),\n    "fun": (\n        "шутк", "анекдот", "факт", "игра", "угада",\n        "joke", "fact", "game", "guess",\n    ),\n    "info": ("новост", "news", "headline"),\n}\n\n# Если ничего не совпало — скромный набор на каждый день\nDEFAULT_GROUPS = ("system", "notes", "calendar", "info")\n\n# Какой группе принадлежит инструмент (для sticky-логики)\n_TOOL_TO_GROUP = {}\nfor _g, _names in GROUPS.items():\n    for _n in _names:\n        _TOOL_TO_GROUP[_n] = _g\n\n\n_last_groups = set()\n\n\ndef _detect(q: str) -> set:\n    return {g for g, words in TRIGGERS.items() if any(w in q for w in words)}\n\n\ndef note_topic(text: str) -> None:\n    """Запоминает тему реплики, даже если её выполнил быстрый путь без модели.\n    Нужно, чтобы следующее "да, включи" знало, о чём речь."""\n    global _last_groups\n    detected = _detect((text or "").lower())\n    if detected:\n        _last_groups = detected\n\n\ndef groups_for(question: str) -> set:\n    """Определяет группы инструментов по тексту запроса. Короткие реплики\n    ("да, включи", "а громче?") наследуют тему предыдущей."""\n    global _last_groups\n    q = question.lower()\n    found = _detect(q)\n    if len(q.split()) <= 6 and _last_groups:\n        found |= _last_groups\n    if found:\n        _last_groups = set(found)\n    else:\n        found = set(DEFAULT_GROUPS)\n    # Медиа почти всегда требует браузера — плееры живут на страницах\n    if "media" in found:\n        found.add("browser")\n    return found\n\n\ndef group_of_tool(tool_name: str):\n    """Группа, к которой относится инструмент (или None)."""\n    return _TOOL_TO_GROUP.get(tool_name)\n\n\ndef filter_schema(full_schema: list, active_groups: set) -> list:\n    """Оставляет в схеме только инструменты из CORE и активных групп."""\n    allowed = set(CORE)\n    for g in active_groups:\n        allowed |= GROUPS.get(g, set())\n    return [t for t in full_schema\n            if t.get("function", {}).get("name") in allowed]\n\n# ---------------------------------------------------------------------------\n# Семантический роутер: инструменты по смыслу запроса, а не только по словам\n# ---------------------------------------------------------------------------\nimport re as _re\nimport numpy as _np\n\nSEMANTIC_TOP_K = 8          # сколько инструментов брать по смыслу\nSEMANTIC_MIN_SIM = 0.2      # ниже — инструмент к запросу не относится\n_tool_index = {"names": None, "mat": None}\n\n\ndef _build_tool_index(full_schema: list) -> None:\n    from file_search import _embed          # та же MiniLM, что в поиске файлов\n    names, texts = [], []\n    for t in full_schema:\n        f = t["function"]\n        names.append(f["name"])\n        texts.append(f"{f[\'name\'].replace(\'_\', \' \')}: {f.get(\'description\', \'\')}")\n    _tool_index["names"] = names\n    _tool_index["mat"] = _embed(texts)\n\n\ndef semantic_tools(question: str, full_schema: list, k: int = SEMANTIC_TOP_K) -> set:\n    from file_search import _embed\n    if _tool_index["mat"] is None:\n        _build_tool_index(full_schema)\n    q = _re.sub(r"^\\s*\\([^)]*\\)\\s*", "", question)      # убираем подсказку языка в начале\n    sims = _tool_index["mat"] @ _embed([q])[0]\n    names = _tool_index["names"]\n    return {names[j] for j in _np.argsort(-sims)[:k] if sims[j] >= SEMANTIC_MIN_SIM}\n\n\nSEMANTIC_KEYWORD_K = 25     # из групп по ключевым словам — только инструменты из топ-25 по смыслу\n_used_groups = set()        # группы инструментов, реально вызванных в прошлом ходе\n\n\ndef mark_used(tool_name: str) -> None:\n    """Модель вызвала инструмент — его группа пригодится следующей реплике («50» после игры)."""\n    g = _TOOL_TO_GROUP.get(tool_name)\n    if g:\n        _used_groups.add(g)\n\n\ndef _semantic_ranking(question: str, full_schema: list) -> list:\n    from file_search import _embed\n    if _tool_index["mat"] is None:\n        _build_tool_index(full_schema)\n    q = _re.sub(r"^\\s*\\([^)]*\\)\\s*", "", question)\n    sims = _tool_index["mat"] @ _embed([q])[0]\n    return [(_tool_index["names"][j], float(sims[j])) for j in _np.argsort(-sims)]\n\n\ndef smart_schema(question: str, full_schema: list, groups: set) -> list:\n    """CORE\n     + топ-8 инструментов по смыслу\n     + из групп по ключевым словам — только близкие по смыслу\n       («play the game» не тянет весь браузер и плееры)\n     + группы, реально использованные в прошлом ходе."""\n    global _used_groups\n    allowed = set(CORE)\n    for g in _used_groups:\n        allowed |= GROUPS.get(g, set())\n    _used_groups = set()\n    try:\n        ranking = _semantic_ranking(question, full_schema)\n        allowed |= {n for n, s in ranking[:SEMANTIC_TOP_K] if s >= SEMANTIC_MIN_SIM}\n        if set(groups) != set(DEFAULT_GROUPS):\n            near = {n for n, _ in ranking[:SEMANTIC_KEYWORD_K]}\n            for g in groups:\n                grp = GROUPS.get(g, set())\n                # маленькие группы (зрение, игры) — целиком: дёшево и надёжно\n                allowed |= grp if len(grp) <= 4 else grp & near\n    except Exception as e:\n        print(f"[router] семантика недоступна ({e}) — беру группы по ключевым словам")\n        for g in groups:\n            allowed |= GROUPS.get(g, set())\n    return [t for t in full_schema if t["function"]["name"] in allowed]\n\ndef add_group(active_schema: list, full_schema: list, group) -> list:\n    """Модель вызвала инструмент из новой группы — добавляем её инструменты."""\n    have = {t["function"]["name"] for t in active_schema}\n    extra = [t for t in full_schema\n             if t["function"]["name"] in GROUPS.get(group, set())\n             and t["function"]["name"] not in have]\n    return active_schema + extra\n\ndef register_tool(name: str, group: str) -> None:\n    """Навык из реестра → в свою группу; смысловой индекс пересоберётся."""\n    GROUPS.setdefault(group, set()).add(name)\n    _TOOL_TO_GROUP[name] = group\n    _tool_index["mat"] = None\n\n# Зрение: явные слова про экран и клики\nTRIGGERS["vision"] = ("жми", "нажми", "кликни", "ткни", "click", "press", "экран", "screen",\n                      "в окне", "window", "что написано", "переведи то")\n\nTRIGGERS["missions"] = ("в фоне", "фонов", "мисси", "background", "mission",\n                        "исследуй", "research", "собери", "сравни несколько")'}


def p(rel):
    return os.path.join(ROOT, *rel.split("/"))


def restore(backup):
    for rel in ORIG:
        shutil.copy2(os.path.join(backup, *rel.split("/")), p(rel))
    print(f"Вернул прежние файлы из {backup}.")


if "--rollback" in sys.argv:
    cands = sorted(d for d in os.listdir(ROOT) if d.startswith("backup_cloudfix2_"))
    if not cands:
        sys.exit("Резервной копии нет.")
    restore(p(cands[-1]))
    sys.exit(0)
if "def _bare(" in open(p("brain/planner.py"), encoding="utf-8").read():
    sys.exit("Уже установлено. Проверка: python tests/test_cloud_brain.py")

differ = []
for rel, h in ORIG.items():
    if not os.path.exists(p(rel)):
        differ.append(f"{rel} — нет файла")
        continue
    got = hashlib.sha256(open(p(rel), "rb").read().replace(b"\r\n", b"\n")).hexdigest()
    if got != h:
        differ.append(rel)
if differ:
    print("  ! отличаются от версии на GitHub: " + ", ".join(differ))
    sys.exit("Эти файлы у тебя изменены — ничего не тронул. Сделай git pull (или пришли мне вывод), потом запусти снова.")

backup = p(time.strftime("backup_cloudfix2_%Y%m%d_%H%M%S"))
for rel in ORIG:
    os.makedirs(os.path.dirname(os.path.join(backup, *rel.split("/"))), exist_ok=True)
    shutil.copy2(p(rel), os.path.join(backup, *rel.split("/")))
print(f"Резервная копия: {backup}")
for rel, s in NEW.items():
    with open(p(rel), "w", encoding="utf-8", newline="\n") as f:
        f.write(s)
print("  ✓ скорость: подсказка телефона больше не включает долгие размышления на каждый вопрос")
print("  ✓ облако знает, что умеет: календарь, почта, перевод, сайты — без «нет доступа к компьютеру»")
print("  ✓ «работает ли сайт …» находит проверку; перевод в скобках читается вслух")

env = dict(os.environ, PYTHONIOENCODING="utf-8", PYTHONUTF8="1")
suites = [f for f in sorted(os.listdir(p("tests"))) if f.startswith("test_") and f.endswith(".py")]
for suite in suites:
    try:
        r = subprocess.run([sys.executable, p("tests/" + suite)], cwd=ROOT, capture_output=True, text=True,
                           encoding="utf-8", errors="replace", timeout=300, env=env)
        out, code = r.stdout + r.stderr, r.returncode
    except subprocess.TimeoutExpired:
        out, code = "✗ тесты не закончились за 5 минут", 1
    m = re.search(r"Тестов пройдено: (\d+) из (\d+)", out)
    good = code == 0 and m and m.group(1) == m.group(2)
    print(f"  {'✓' if good else '✗'} tests/{suite}: {m.group(0) if m else 'итоговой строки нет'}")
    if not good:
        lines = out.splitlines()
        for i, ln in enumerate(lines):
            if ln.strip().startswith("✗"):
                print("      " + "\n      ".join(x.rstrip() for x in lines[i:i + 7]))
        restore(backup)
        sys.exit("✗ Проверка не прошла — всё возвращено.")
print("\nГотово. Дальше: git add -A, git commit, git push — Render обновится сам за 3–5 минут.")
